def comps(I,bg):
    seen=set(); out={}
    import sys
    from collections import deque
    H=len(I);W=len(I[0])
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) not in seen:
                c=I[i][j];st=[(i,j)];comp=[]
                while st:
                    y,x=st.pop()
                    if(y,x) in seen or I[y][x]!=c:continue
                    seen.add((y,x));comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W: st.append((ny,nx))
                out.setdefault(c,[]).append(comp)
    return out
